# Counts the uppercase letters and converts the whole word to whichever case is in the majority
word = input()
string = list(word)

num_upper = 0
for i in range(0, len(string)):
    if (string[i].isupper()):
        num_upper += 1

num_lower = len(string) - num_upper

if (num_upper > num_lower):
    print(word.upper())
else:
    print(word.lower())

